import { cacheTag } from 'next/cache';

export type Post = {
  id: number;
  title: string;
  body: string;
};

// In-memory store for demonstration purposes
const posts: Post[] = [
  { id: 1, title: 'Hello World', body: 'This is the first post.' },
];
let nextId = 2;

export async function getPosts(): Promise<Post[]> {
  'use cache';
  cacheTag('posts');

  // Simulate async data fetching (e.g., a database call)
  return [...posts];
}

export function addPost(title: string, body: string): Post {
  const post: Post = { id: nextId++, title, body };
  posts.push(post);
  return post;
}

