'use server';

import { revalidateTag } from 'next/cache';
import { addPost } from '@/app/lib/posts';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const body = formData.get('body') as string;

  addPost(title, body);

  // Purges all cache entries tagged "posts".
  // The next page load is forced to fetch fresh data — no stale
  // content is ever served, unlike time-based (ISR) revalidation.
  revalidateTag('posts');
}

